    42	async function fetchDebugDirectEvents(city = 'Stockholm') {
    43	  const results = { events: [], ticketmaster: {}, otherSources: {} };
    44	  
    45	  // Ticketmaster
    46	  try {
    47	    const url = `https://app.ticketmaster.com/discovery/v2/events.json?apikey=${TICKETMASTER_API_KEY}&city=${city}&countryCode=SE&size=50&sort=date,asc`;
    48	    const response = await axios.get(url, { timeout: 15000 });
    49	    
    50	    if (response.data?._embedded?.events) {
    51	      results.ticketmaster.events = response.data._embedded.events.map(ev => ({
    52	        id: ev.id,
    53	        title: ev.name,
    54	        date: ev.dates?.start?.localDate || '',
    55	        time: ev.dates?.start?.localTime ? ev.dates.start.localTime.substring(0, 5) : '',
    56	        venue: ev._embedded?.venues?.[0]?.name || 'Unknown',
    57	        area: ev._embedded?.venues?.[0]?.city?.name || city,
    58	        source: 'ticketmaster',
    59	        imageUrl: ev.images?.[0]?.url || null,
    60	      }));
    61	      results.ticketmaster.count = results.ticketmaster.events.length;
    62	    }
    63	  } catch (e) {
    64	    console.log('[debug] Ticketmaster:', e.message);
    65	  }
    66	  
    67	  // Kulturhuset
    68	  try {
    69	    const esResp = await axios.post(
    70	      'https://elastic.kulturhusetstadsteatern.se/khst-events/_search',
    71	      { size: 20, query: { bool: { must: [{ range: { tixStartDate: { gte: 'now' } } }] } }, sort: [{ tixStartDate: { order: 'asc' } }] },
    72	      { timeout: 10000, headers: { 'Content-Type': 'application/json' } }
    73	    );
    74	    if (esResp.data?.hits?.hits) {
    75	      results.otherSources.kulturhuset = esResp.data.hits.hits.map(h => ({
    76	        id: h._id,
    77	        title: h._source?.drupalTitle || h._source?.tixName || 'Untitled',
    78	        date: (h._source?.tixStartDate || '').split('T')[0],
    79	        source: 'kulturhuset',
    80	      }));
    81	    }
    82	  } catch (e) {
    83	    console.log('[debug] Kulturhuset:', e.message);
    84	  }
    85	  
    86	  return results;
    87	}
