    89	/**
    90	 * Health check with explicit freshness data
    91	 */
    92	async function handleHealth(req, res) {
    93	  let ingestionStatus = { supabase: supabase ? 'connected' : 'disconnected' };
    94	  
    95	  if (supabase) {
    96	    try {
    97	      // Get latest ingestion log
    98	      const { data: latestRun } = await supabase
    99	        .from('ingestion_logs')
   100	        .select('source, action, timestamp')
   101	        .order('timestamp', { ascending: false })
   102	        .limit(1);
   103	      
   104	      // Get event timestamps
   105	      const { data: eventTimes } = await supabase
   106	        .from('events')
   107	        .select('created_at, updated_at, start_time')
   108	        .eq('status', 'published')
   109	        .order('start_time', { ascending: false })
   110	        .limit(1);
   111	      
   112	      // Get events last 24h
   113	      const last24h = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
   114	      const { count: events24h } = await supabase
   115	        .from('events')
   116	        .select('id', { count: 'exact', head: true })
   117	        .eq('status', 'published')
   118	        .gte('start_time', last24h);
   119	      
   120	      // Get active sources
   121	      const now = new Date().toISOString();
   122	      const { data: activeSources } = await supabase
   123	        .from('events')
   124	        .select('source')
   125	        .eq('status', 'published')
   126	        .gte('start_time', now);
   127	      
   128	      ingestionStatus = {
   129	        supabase: 'connected',
   130	        last_ingestion_run: latestRun?.[0]?.timestamp || null,
   131	        events_last_24h: events24h || 0,
   132	        newest_event: eventTimes?.[0]?.start_time || null,
   133	        newest_updated: eventTimes?.[0]?.updated_at || null,
   134	        oldest_event: null, // Would need separate query
   135	        active_sources: [...new Set((activeSources || []).map(e => e.source))],
   136	        active_sources_count: [...new Set((activeSources || []).map(e => e.source))].length,
   137	      };
   138	    } catch (err) {
   139	      ingestionStatus.supabase = 'error';
   140	      ingestionStatus.error = err.message;
   141	    }
   142	  }
   143	  
   144	  res.writeHead(200, { 'Content-Type': 'application/json' });
   145	  res.end(JSON.stringify({ 
   146	    status: 'ok', 
   147	    timestamp: new Date().toISOString(),
   148	    ticketmasterKey: TICKETMASTER_API_KEY ? 'configured' : 'missing',
   149	    ingestion: ingestionStatus
   150	  }));
   151	}
