   153	/**
   154	 * PRIMARY: Fetch events from Supabase with full metadata
   155	 */
   156	async function handleSupabaseEvents(req, res) {
   157	  if (!supabase) {
   158	    res.writeHead(503, { 'Content-Type': 'application/json' });
   159	    res.end(JSON.stringify({ error: 'Supabase not configured', data_source: 'none' }));
   160	    return;
   161	  }
   162	
   163	  const url = new URL(req.url, `http://localhost:${PORT}`);
   164	  const city = url.searchParams.get('city') || 'Stockholm';
   165	  const days = parseInt(url.searchParams.get('days') || '365');
   166	  const limit = parseInt(url.searchParams.get('limit') || '100');
   167	  const source = url.searchParams.get('source') || null;
   168	
   169	  try {
   170	    const now = new Date();
   171	    const startDate = now.toISOString();
   172	    const endDate = new Date(now.getTime() + days * 24 * 60 * 60 * 1000).toISOString();
   173	    const last24h = new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString();
   174	
   175	    // Get ingestion stats
   176	    let ingestionStats = null;
   177	    try {
   178	      const { data: logs } = await supabase
   179	        .from('ingestion_logs')
   180	        .select('source, action, timestamp')
   181	        .gte('timestamp', last24h)
   182	        .order('timestamp', { ascending: false });
   183	      
   184	      if (logs?.length) {
   185	        const bySource = {};
   186	        logs.forEach(log => {
   187	          bySource[log.source] = bySource[log.source] || { inserted: 0, updated: 0 };
   188	          bySource[log.source][log.action]++;
   189	        });
   190	        ingestionStats = { events_last_24h: logs.length, by_source: bySource, last_run: logs[0].timestamp };
   191	      }
   192	    } catch (e) {
   193	      console.warn('[api] Could not fetch ingestion stats:', e.message);
   194	    }
   195	
   196	    // Get total count
   197	    const { count: totalCount } = await supabase
   198	      .from('events')
   199	      .select('id', { count: 'exact', head: true })
   200	      .eq('status', 'published');
   201	
   202	    // Get source counts
   203	    const { data: sourceCounts } = await supabase
   204	      .from('events')
   205	      .select('source')
   206	      .eq('status', 'published')
   207	      .gte('start_time', startDate)
   208	      .lte('start_time', endDate);
   209	    
   210	    const sourceCountsMap = {};
   211	    (sourceCounts || []).forEach(e => {
   212	      sourceCountsMap[e.source] = (sourceCountsMap[e.source] || 0) + 1;
   213	    });
   214	
   215	    // Get active sources
   216	    const { data: activeSourcesData } = await supabase
   217	      .from('events')
   218	      .select('source')
   219	      .eq('status', 'published')
   220	      .gte('start_time', startDate);
   221	    
   222	    const activeSourceKeys = [...new Set((activeSourcesData || []).map(e => e.source))];
   223	
   224	    // Build query
   225	    let query = supabase
   226	      .from('events')
   227	      .select(`id, title_en, title_sv, description_en, description_sv, start_time, end_time, source, venue_id, venues:venue_id(name, address), category_slug, is_free, price_min_sek, price_max_sek, ticket_url, image_url`)
   228	      .gte('start_time', startDate)
   229	      .lte('start_time', endDate)
   230	      .eq('status', 'published')
   231	      .order('start_time', { ascending: true })
   232	      .limit(limit);
   233	
   234	    if (source) query = query.eq('source', source);
   235	
   236	    const { data: events, error } = await query;
   237	
   238	    if (error) {
   239	      res.writeHead(500, { 'Content-Type': 'application/json' });
   240	      res.end(JSON.stringify({ error: error.message, data_source: 'supabase' }));
   241	      return;
   242	    }
   243	
   244	    // UNIFIED EVENT SHAPE
   245	    const transformedEvents = (events || []).map(ev => ({
   246	      id: ev.id,
   247	      title: ev.title_en || ev.title_sv || 'Untitled',
   248	      date: ev.start_time ? ev.start_time.split('T')[0] : '',
   249	      time: ev.start_time ? ev.start_time.split('T')[1]?.substring(0, 5) : '',
   250	      venue_name: ev.venues?.name || '',
   251	      venue_address: ev.venues?.address || '',
   252	      city: city,
   253	      description: ev.description_en || ev.description_sv || '',
   254	      source: ev.source,
   255	      category_slug: ev.category_slug || 'community',
   256	      is_free: ev.is_free || false,
   257	      price_min: ev.price_min_sek,
   258	      price_max: ev.price_max_sek,
   259	      ticket_url: ev.ticket_url || '',
   260	      image_url: ev.image_url || null,
   261	      // Legacy aliases
   262	      venue: ev.venues?.name || '',
   263	      area: city,
   264	      url: ev.ticket_url || '',
   265	      category: ev.category_slug || 'culture',
   266	      isFree: ev.is_free || false,
   267	      priceMin: ev.price_min_sek,
   268	      priceMax: ev.price_max_sek,
   269	      imageUrl: ev.image_url,
   270	    }));
   271	
   272	    // Sources for dropdown - ONLY canonical
   273	    const sources = filterCanonicalSources(activeSourceKeys);
   274	
   275	    res.writeHead(200, { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' });
   276	    res.end(JSON.stringify({
   277	      data_source: 'supabase',
   278	      fallback_used: false,
   279	      timestamp: new Date().toISOString(),
   280	      ingestion_stats: ingestionStats,
   281	      total_published_events: totalCount || 0,
   282	      source_counts: sourceCountsMap,
   283	      sources: sources,
   284	      events: transformedEvents,
   285	      count: transformedEvents.length,
   286	      query_params: { city, days, limit, source }
   287	    }));
   288	  } catch (err) {
   289	    console.error('[api] Supabase fetch error:', err);
   290	    res.writeHead(500, { 'Content-Type': 'application/json' });
   291	    res.end(JSON.stringify({ error: err.message, data_source: 'supabase' }));
   292	  }
   293	}
