   328	const server = http.createServer(async (req, res) => {
   329	  const url = new URL(req.url, `http://localhost:${PORT}`);
   330	  console.log(`[${new Date().toISOString()}] ${req.method} ${url.pathname}`);
   331	  
   332	  if (url.pathname === '/health') {
